/* This function will load the configured users appended to the server
 * configuration via ACLAppendUserForLoading(). On loading errors it will
 * log an error and return C_ERR, otherwise C_OK will be returned. */
static int ACLLoadConfiguredUsers(void) {
    listIter li;
    listNode *ln;
    listRewind(UsersToLoad, &li);
    while ((ln = listNext(&li)) != NULL) {
        sds *aclrules = listNodeValue(ln);
        sds username = aclrules[0];

        if (ACLStringHasSpaces(aclrules[0], sdslen(aclrules[0]))) {
            serverLog(LL_WARNING, "Spaces not allowed in ACL usernames");
            return C_ERR;
        }

        user *u = ACLCreateUser(username, sdslen(username));
        if (!u) {
            /* Only valid duplicate user is the default one. */
            serverAssert(!strcmp(username, "default"));
            u = ACLGetUserByName("default", 7);
            ACLSetUser(u, "reset", -1);
        }

        /* Load every rule defined for this user. */
        for (int j = 1; aclrules[j]; j++) {
            if (ACLSetUser(u, aclrules[j], sdslen(aclrules[j])) != C_OK) {
                const char *errmsg = ACLSetUserStringError();
                serverLog(LL_WARNING,
                          "Error loading ACL rule '%s' for "
                          "the user named '%s': %s",
                          aclrules[j], aclrules[0], errmsg);
                return C_ERR;
            }
        }

        /* Having a disabled user in the configuration may be an error,
         * warn about it without returning any error to the caller. */
        if (u->flags & USER_FLAG_DISABLED) {
            serverLog(LL_NOTICE,
                      "The user '%s' is disabled (there is no "
                      "'on' modifier in the user description). Make "
                      "sure this is not a configuration error.",
                      aclrules[0]);
        }
    }
    return C_OK;
}

/* Bind a client to an ACL user.
 *
 * When reloading is 0, the client is attached to the default user and the
 * authenticated flag is initialized from that user's flags. This covers new
 * connections and connection resets.
 *
 * When reloading is 1, the client is rebound to the user of the same name in
 * the newly loaded ACL table. If that user no longer exists, or the client's
 * Pub/Sub subscriptions are no longer permitted, the client is disconnected.
 */
void ACLBindClientUser(client *c, rax *user_channels, int reloading) {
    if (!reloading) {
        c->user = DefaultUser;
        c->flag.authenticated = (c->user->flags & USER_FLAG_NOPASS) && !(c->user->flags & USER_FLAG_DISABLED);
        return;
    }

    user *original = c->user;
    list *channels = NULL;
    user *new_user = NULL;
    raxFind(Users, (unsigned char *)original->name, sdslen(original->name), (void **)&new_user);
    if (new_user && user_channels) {
        if (!raxFind(user_channels, (unsigned char *)(new_user->name), sdslen(new_user->name), (void **)&channels)) {
            channels = getUpcomingChannelList(new_user, original);
            raxInsert(user_channels, (unsigned char *)(new_user->name), sdslen(new_user->name), channels, NULL);
        }
    }

    /* When the new channel list is NULL, it means the new user's channel list is a superset of the old user's
     * list. */
    if (!new_user) {
        freeClient(c);
        return;
    }
    if (channels && getClientType(c) == CLIENT_TYPE_PUBSUB) {
        ClientPubSubData *pubsub = c->pubsub_data;
        int has_patterns = dictSize(pubsub->pubsub_patterns) != 0;
        int has_channels = dictSize(pubsub->pubsub_channels) != 0;
        int has_shard_channels = dictSize(pubsub->pubsubshard_channels) != 0;
        if ((has_patterns || has_channels || has_shard_channels) && ACLShouldKillPubsubClient(c, channels)) {
            freeClient(c);
            return;
        }
    }
    c->user = new_user;
}

