void ACLBindClientUser(client *c, rax *user_channels, int reloading) {
    if (!reloading) {
        c->user = DefaultUser;
        c->flag.authenticated = (c->user->flags & USER_FLAG_NOPASS) && !(c->user->flags & USER_FLAG_DISABLED);
        return;
    }

    /* The primary client on a replica has a NULL user (it is allowed to do
     * everything) and must not be rebound to a user from the loaded ACL. */
    if (c->user == NULL) return;

    user *original = c->user;

